CREATE TABLE customer (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(60), phone VARCHAR(30) UNIQUE, level_name VARCHAR(20), balance DECIMAL(10,2), points INT);
CREATE TABLE account (username VARCHAR(64) PRIMARY KEY, customer_id BIGINT, employee_id BIGINT, password_hash VARCHAR(100), role_code VARCHAR(20), display_name VARCHAR(60), title VARCHAR(60), enabled TINYINT NOT NULL DEFAULT 1, account_version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE pet (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT, name VARCHAR(60), species VARCHAR(10), breed VARCHAR(60), size_type VARCHAR(15), weight DECIMAL(5,2), coat VARCHAR(30), health_note VARCHAR(300), age_band VARCHAR(20), allergy VARCHAR(40), skin_history VARCHAR(40), grooming_history VARCHAR(40));
CREATE TABLE service (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80), category VARCHAR(30), price DECIMAL(10,2), duration INT, species VARCHAR(10), enabled TINYINT NOT NULL DEFAULT 1);
CREATE TABLE service_price (service_id BIGINT NOT NULL, size_type VARCHAR(15) NOT NULL, price DECIMAL(10,2) NOT NULL, duration INT NOT NULL, PRIMARY KEY(service_id,size_type));
CREATE TABLE employee (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(60), title VARCHAR(60), skills VARCHAR(200), species VARCHAR(30), sizes VARCHAR(80), enabled TINYINT NOT NULL DEFAULT 1);
CREATE TABLE resource (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(80), species VARCHAR(20), enabled TINYINT NOT NULL DEFAULT 1);
CREATE TABLE booking_lock (id INT PRIMARY KEY);
CREATE TABLE employee_schedule (employee_id BIGINT NOT NULL, schedule_date DATE NOT NULL, status VARCHAR(10) NOT NULL, start_time TIME, end_time TIME, PRIMARY KEY(employee_id,schedule_date));
CREATE TABLE appointment (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT, pet_id BIGINT, service_id BIGINT, employee_id BIGINT, resource_id BIGINT, appointment_date DATE, start_time TIME, end_time TIME, price DECIMAL(10,2), status VARCHAR(30));
CREATE TABLE grooming (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pet_id BIGINT, customer_id BIGINT, employee_id BIGINT, service_id BIGINT, stage VARCHAR(30), status VARCHAR(30), pickup_code VARCHAR(10), appointment_id BIGINT UNIQUE, resource_id BIGINT, base_price DECIMAL(10,2), precheck_note VARCHAR(300));
CREATE TABLE grooming_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, grooming_id BIGINT NOT NULL, event_type VARCHAR(30) NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE addon (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, grooming_id BIGINT, name VARCHAR(100), reason VARCHAR(300), amount DECIMAL(10,2), status VARCHAR(20), request_id VARCHAR(36) UNIQUE);
CREATE TABLE product (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100), stock INT, threshold INT, unit VARCHAR(20), price DECIMAL(10,2) NOT NULL DEFAULT 0, sale_units INT NOT NULL DEFAULT 1, image_key VARCHAR(64));
CREATE TABLE inventory_flow (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id BIGINT NOT NULL, delta INT NOT NULL, stock_after INT NOT NULL, action VARCHAR(20) NOT NULL, reference_id BIGINT, reason VARCHAR(255) NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL, request_id VARCHAR(36) UNIQUE);
CREATE TABLE service_consumption (service_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, PRIMARY KEY(service_id,product_id));
CREATE TABLE prepaid_card (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT, name VARCHAR(100), remaining INT, total INT);
CREATE TABLE prepaid_card_service (card_id BIGINT NOT NULL, service_id BIGINT NOT NULL, PRIMARY KEY(card_id, service_id));
CREATE TABLE service_settlement (grooming_id BIGINT PRIMARY KEY, customer_id BIGINT NOT NULL, base_amount DECIMAL(10,2) NOT NULL, addon_amount DECIMAL(10,2) NOT NULL, amount DECIMAL(10,2) NOT NULL, method VARCHAR(20) NOT NULL, card_id BIGINT, status VARCHAR(20) NOT NULL, operator_name VARCHAR(64) NOT NULL, paid_at TIMESTAMP NOT NULL, refunded_at TIMESTAMP, refund_reason VARCHAR(255), trade_no VARCHAR(64));
CREATE TABLE prepaid_card_flow (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, card_id BIGINT NOT NULL, grooming_id BIGINT NOT NULL, change_times INT NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE balance_flow (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL, grooming_id BIGINT, amount DECIMAL(10,2) NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE member_lock (id INT PRIMARY KEY);
CREATE TABLE member_recharge (request_id VARCHAR(36) PRIMARY KEY, customer_id BIGINT NOT NULL, amount DECIMAL(10,2) NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE prepaid_card_sale (request_id VARCHAR(36) PRIMARY KEY, card_id BIGINT NOT NULL UNIQUE, customer_id BIGINT NOT NULL, amount DECIMAL(10,2) NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE review (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_name VARCHAR(60), pet_name VARCHAR(60), rating INT, content VARCHAR(500), grooming_id BIGINT UNIQUE);
CREATE TABLE health_record (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, pet_id BIGINT NOT NULL, grooming_id BIGINT, employee_id BIGINT, recorded_on DATE NOT NULL, weight DECIMAL(5,2) NOT NULL, skin_code VARCHAR(30) NOT NULL, coat_code VARCHAR(30) NOT NULL, ear_code VARCHAR(30) NOT NULL, score INT NOT NULL, groomer_note VARCHAR(300));
CREATE TABLE retail_order (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(100) NOT NULL, quantity INT NOT NULL, unit_price DECIMAL(10,2) NOT NULL, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL, stock_units INT NOT NULL DEFAULT 1, request_id VARCHAR(36) UNIQUE, pay_method VARCHAR(20));
CREATE TABLE sale_lock (id INT PRIMARY KEY);
CREATE TABLE retail_order_event (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id BIGINT NOT NULL, action VARCHAR(20) NOT NULL, amount DECIMAL(10,2) NOT NULL, reason VARCHAR(255) NOT NULL, operator_name VARCHAR(64) NOT NULL, created_at TIMESTAMP NOT NULL);
CREATE TABLE payment_order (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, payment_no VARCHAR(64) NOT NULL UNIQUE, grooming_id BIGINT, customer_id BIGINT NOT NULL, channel VARCHAR(20) NOT NULL, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) NOT NULL, trade_no VARCHAR(64), qr_code VARCHAR(500), expire_at TIMESTAMP NOT NULL, paid_at TIMESTAMP, created_at TIMESTAMP NOT NULL, biz_type VARCHAR(20) NOT NULL DEFAULT 'GROOMING', related_id BIGINT);
CREATE TABLE store_settings (id INT PRIMARY KEY, store_name VARCHAR(100) NOT NULL, business_hours VARCHAR(50) NOT NULL, open_time VARCHAR(10) NOT NULL, close_time VARCHAR(10) NOT NULL, buffer_minutes INT NOT NULL, address VARCHAR(255) NOT NULL, phone VARCHAR(50) NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE notification (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, target_role VARCHAR(20) NOT NULL, customer_id BIGINT, category VARCHAR(50) NOT NULL, title VARCHAR(100) NOT NULL, content VARCHAR(500) NOT NULL, related_no VARCHAR(64), unread TINYINT NOT NULL DEFAULT 1, urgent TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL);
CREATE TABLE audit_log (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, action_type VARCHAR(50) NOT NULL, operator_name VARCHAR(64) NOT NULL, target_type VARCHAR(50) NOT NULL, target_id VARCHAR(64) NOT NULL, details VARCHAR(1000), created_at TIMESTAMP NOT NULL);
